import os as _os

def _oracle_write(text):
    _os.write(1, (text + '\n').encode())
import dis
import opcode
from _opcode import stack_effect

def _t():
    assert stack_effect(dis.opmap['POP_TOP']) == -1, ('assertEqual', stack_effect(dis.opmap['POP_TOP']), -1)
    assert stack_effect(dis.opmap['BUILD_SLICE'], 2) == -1, ('assertEqual', stack_effect(dis.opmap['BUILD_SLICE'], 2), -1)
    assert stack_effect(dis.opmap['BUILD_SLICE'], 3) == -2, ('assertEqual', stack_effect(dis.opmap['BUILD_SLICE'], 3), -2)
    try:
        stack_effect(*(30000,))
    except ValueError:
        pass
    has_arg = dis.hasarg
    for name, code in filter(lambda item: item[0] not in dis.deoptmap, dis.opmap.items()):
        if code >= opcode.MIN_INSTRUMENTED_OPCODE:
            continue
        stack_effect(code)
        stack_effect(code, 0)
    for code in set(range(256)) - set(dis.opmap.values()):
        try:
            stack_effect(*(code,))
        except ValueError:
            pass
        try:
            stack_effect(*(code, 0))
        except ValueError:
            pass
try:
    _t()
except BaseException as _e:
    _oracle_write('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    _oracle_write('ok')
